import re

def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    # Regex to find patterns of digits followed by h, m, or s
    # The use of fullmatch ensures the entire string conforms to the pattern
    # and contains no invalid characters or extra spaces.
    if not re.fullmatch(r'(\d+h|\d+m|\d+s)+', s):
        raise ValueError("Invalid duration string")

    matches = re.findall(r'(\d+)([hms])', s)
    total_seconds = 0

    for value, unit in matches:
        num = int(value)
        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num

    return total_seconds
