def parse_headers(raw: str) -> dict[str, str]:
    headers = {}
    # Split the raw string into lines, handling both \n and \r\n
    for line in raw.splitlines():
        # Skip blank lines (lines that are empty or only whitespace)
        if not line.strip():
            continue

        # Raise ValueError if the line does not contain a colon
        if ':' not in line:
            raise ValueError("Header line missing ':'")

        # Only the first ':' separates name and value
        name, value = line.split(':', 1)

        # Names are case-insensitive and returned in lowercase
        # Values are stripped of surrounding whitespace
        name_key = name.lower()
        value = value.strip()

        if name_key not in headers:
            headers[name_key] = []
        headers[name_key].append(value)

    # Join repeated headers with ', ' in order of appearance
    return {name: ", ".join(values) for name, values in headers.items()}
