def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    units = [(10**9, "bi"), (10**6, "mi"), (10**3, "mil")]

    for magnitude, label in units:
        val = n / magnitude
        # Round half up to 1 decimal place
        rounded = int(val * 10 + 0.5) / 10.0

        # If the rounded value is less than 1000, it's the correct unit
        if rounded < 1000:
            # Format with one decimal place and a comma
            # Remove trailing .0 for cleaner output as per "drop a trailing ,0"
            if rounded == int(rounded):
                return f"{int(rounded)} {label}"
            else:
                return f"{rounded:,}".replace(".", ",") + " " + label

    # Fallback for extremely large numbers (beyond billion)
    # Since the prompt only specifies bi as the highest unit
    val = n / 10**9
    rounded = int(val * 10 + 0.5) / 10.0
    if rounded == int(rounded):
        return f"{int(rounded)} bi"
    else:
        return f"{rounded:,}".replace(".", ",") + " bi"
