def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        # Ignore build metadata
        v = v.split('+')[0]

        if '-' in v:
            main_str, pre_str = v.split('-', 1)
            pre_parts = []
            for part in pre_str.split('.'):
                if part.isdigit():
                    pre_parts.append(int(part))
                else:
                    pre_parts.append(part)
            return [int(x) for x in main_str.split('.')], pre_parts
        else:
            return [int(x) for x in v.split('.')], []

    main_a, pre_a = parse_version(a)
    main_b, pre_b = parse_version(b)

    # Compare main version numbers
    if main_a != main_b:
        return 1 if main_a > main_b else -1

    # If main versions are equal, check pre-release status
    # A release version has higher precedence than a pre-release version
    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1

    # Compare pre-release identifiers dot by dot
    for p_a, p_b in zip(pre_a, pre_b):
        if type(p_a) == type(p_b):
            if p_a != p_b:
                return 1 if p_a > p_b else -1
        else:
            # Numeric identifiers are lower than alphanumeric ones
            return -1 if isinstance(p_a, int) else 1

    # If all preceding identifiers are equal, the shorter list is lower
    if len(pre_a) != len(pre_b):
        return 1 if len(pre_a) > len(pre_b) else -1

    return 0
