import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Identify all unique nodes in the graph
    all_nodes = set(deps.keys())
    for d_list in deps.values():
        for d in d_list:
            all_nodes.add(d)

    # Initialize adjacency list and in-degree count
    # Note: if B depends on A, the edge is A -> B
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for node, dependencies in deps.items():
        for d in dependencies:
            adj[d].append(node)
            in_degree[node] += 1

    # Use a min-heap to store nodes with zero in-degree to satisfy 
    # the alphabetical requirement for ties.
    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # If result length is less than total nodes, a cycle exists
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
