import unicodedata

def sort_names(names: list[str]) -> list[str]:
    def sort_key(name: str):
        # Normalize to NFKD to separate base characters from their accents
        # and filter out combining marks.
        normalized = "".join(
            c for c in unicodedata.normalize('NFKD', name)
            if not unicodedata.combining(c)
        ).lower()

        # Determine if the name has accents by comparing the lowercase
        # original to the normalized version.
        has_accents = name.lower() != normalized

        # Sort Priority:
        # 1. Normalized lowercase name (ignoring accents and case)
        # 2. Presence of accents (False/0 comes before True/1)
        # 3. Original string lexicographical order
        return (normalized, has_accents, name)

    return sorted(names, key=sort_key)
