                parts.append(word[i:i + width])
        else:
            parts.append(word)

        for part in parts:
            if not current_line:
                current_line.append(part)
                current_line_len = len(part)
            elif current_line_len + 1 + len(part) <= width:
                current_line.append(part)
                current_line_len += 1 + len(part)
