def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    section_found = False
    key_found = False
    current_section = None

    for i, line in enumerate(lines):
        stripped = line.strip()

        # Check for section headers
        if stripped.startswith('[') and stripped.endswith(']'):
            current_section = stripped[1:-1]
            if current_section == section:
                section_found = True
            elif section_found and current_section != section:
                # If we were in the target section and moved to another
                # without finding the key, the key doesn't exist.
                raise KeyError(f"Key '{key}' not found in section [{section}]")
            continue

        # Process lines within the target section
        if section_found:
            # Ignore comments and blank lines
            if not stripped or stripped.startswith(';') or stripped.startswith('#'):
                continue

            if '=' in stripped:
                k_part, v_part = stripped.split('=', 1)
                if k_part.strip() == key:
                    # Determine if we should preserve the original line ending
                    newline = '\n' if line.endswith('\n') else ''
                    # If the line ended with \r\n, preserve it
                    if line.endswith('\r\n'):
                        newline = '\r\n'

                    lines[i] = f"{key} = {value}{newline}"
                    key_found = True
                    break

    if not section_found:
        raise KeyError(f"Section [{section}] not found")
    if not key_found:
        raise KeyError(f"Key '{key}' not found in section [{section}]")

    return "".join(lines)
