from datetime import datetime

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    latest_map = {}

    for record in records:
        val = record[key]
        # Handle 'Z' suffix for ISO 8601 compatibility in older Python versions
        ts_str = record['updated_at'].replace('Z', '+00:00')
        current_ts = datetime.fromisoformat(ts_str)

        if val not in latest_map:
            latest_map[val] = (current_ts, record)
        else:
            prev_ts, _ = latest_map[val]
            # Update if current record is newer or equal (to satisfy "later in the list" tie-break)
            if current_ts >= prev_ts:
                latest_map[val] = (current_ts, record)

    # Dictionary insertion order is preserved in Python 3.7+
    return [item[1] for item in latest_map.values()]
