import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return False

    # Handle IPv4-mapped IPv6 addresses (e.g., ::ffff:10.0.0.5)
    # These should be treated as the underlying IPv4 address.
    if addr.version == 6:
        packed = addr.packed
        if packed[:10] == b'\x00' * 10 and packed[10:12] == b'\xff\xff':
            addr = ipaddress.IPv4Address(packed[12:])

    for net_str in networks:
        try:
            # strict=False allows networks with host bits set (e.g., 10.0.0.1/8)
            net = ipaddress.ip_network(net_str, strict=False)
        except ValueError:
            raise ValueError(f"Invalid network: {net_str}")

        if addr in net:
            return True

    return False
