import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    graph = {}
    in_degree = {}
    nodes = set()

    # Identify all unique nodes in the dependency graph
    for item, dependencies in deps.items():
        nodes.add(item)
        for d in dependencies:
            nodes.add(d)

    # Initialize graph and in-degree tracking
    for node in nodes:
        graph[node] = []
        in_degree[node] = 0

    # Populate graph and in-degrees
    # The input 'deps' maps an item to the things it depends ON.
    # So, if B depends on A, the edge is A -> B.
    for item, dependencies in deps.items():
        in_degree[item] = len(dependencies)
        for d in dependencies:
            graph[d].append(item)

    # Use a min-heap to ensure we always pick the alphabetically smallest 
    # node among those with zero dependencies (ready nodes).
    ready_queue = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(ready_queue)

    order = []
    while ready_queue:
        u = heapq.heappop(ready_queue)
        order.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(ready_queue, v)

    # If the order does not contain all nodes, there is a cycle.
    if len(order) != len(nodes):
        raise ValueError("Cycle detected in dependencies")

    return order
