import re

def natural_sorted(names: list[str]) -> list[str]:
    def sort_key(s: str) -> list[tuple]:
        # Split the string into parts of digits and non-digits
        parts = re.split(r'(\d+)', s)
        key = []
        for part in parts:
            if part.isdigit():
                # Store as a tuple: (type_priority, integer_value)
                # type_priority 0 ensures numbers are grouped/sorted consistently
                key.append((0, int(part)))
            else:
                # Store as a tuple: (type_priority, lowercase_string)
                # type_priority 1 distinguishes it from numbers
                key.append((1, part.lower()))
        return key

    # Python's sorted() is stable by default
    return sorted(names, key=sort_key)
