import copy

def deep_merge(base: dict, override: dict) -> dict:
    result = {}
    # Identify all keys present in both dictionaries
    all_keys = set(base.keys()) | set(override.keys())

    for key in all_keys:
        if key in override:
            val_override = override[key]
            # Rule: an override value of None deletes the key
            if val_override is None:
                continue

            val_base = base.get(key)

            # Rule: when both values are dicts they are merged recursively
            if isinstance(val_override, dict) and isinstance(val_base, dict):
                result[key] = deep_merge(val_base, val_override)
            else:
                # Rule: lists and other values are replaced, not merged
                # Rule: result must not share nested dicts or lists (deepcopy)
                result[key] = copy.deepcopy(val_override)
        else:
            # Key only exists in the base dictionary
            result[key] = copy.deepcopy(base[key])

    return result
