import math

def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    def format_value(val: float, unit: str) -> str:
        # Round half up to 1 decimal place
        # Use multiply by 10, add 0.5, floor, then divide by 10
        rounded = math.floor(val * 10 + 0.5) / 10.0
        # Format with comma as decimal separator
        s = "{:.1f}".format(rounded).replace('.', ',')
        # Drop trailing ',0'
        if s.endswith(',0'):
            s = s[:-2]
        return f"{s} {unit}"

    # Check units from largest to smallest to handle rounding overflows
    # e.g., 999,950 rounded to 1 decimal at 'mil' is 1000.0, 
    # but it should be '1 mi' based on the prompt.

    # Check Billion
    if (n / 10**9) * 10 + 0.5 >= 10:
        return format_value(n / 10**9, "bi")
    # Check Million
    if (n / 10**6) * 10 + 0.5 >= 10:
        return format_value(n / 10**6, "mi")
    # Otherwise it's Thousand
    return format_value(n / 10**3, "mil")
