def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        # Remove build metadata
        base = v.split('+')[0]
        # Separate release from pre-release
        parts = base.split('-', 1)
        release_parts = [int(x) for x in parts[0].split('.')]
        pre_release = parts[1].split('.') if len(parts) > 1 else None
        return release_parts, pre_release

    rel_a, pre_a = parse_version(a)
    rel_b, pre_b = parse_version(b)

    # Compare release version (Major.Minor.Patch)
    if rel_a > rel_b:
        return 1
    if rel_a < rel_b:
        return -1

    # Handle pre-release logic
    # A release version has higher precedence than a pre-release version
    if pre_a is None and pre_b is not None:
        return 1
    if pre_a is not None and pre_b is None:
        return -1
    if pre_a is None and pre_b is None:
        return 0

    # Both have pre-releases; compare dot by dot
    for p1, p2 in zip(pre_a, pre_b):
        is_num1 = p1.isdigit()
        is_num2 = p2.isdigit()

        if is_num1 and is_num2:
            # Numeric identifiers are compared as numbers
            v1, v2 = int(p1), int(p2)
            if v1 > v2:
                return 1
            if v1 < v2:
                return -1
        elif is_num1 != is_num2:
            # Numeric identifiers are lower than non-numeric identifiers
            return -1 if is_num1 else 1
        else:
            # Both are alphanumeric
            if p1 > p2:
                return 1
            if p1 < p2:
                return -1

    # If all earlier identifiers are equal, the shorter list is lower
    if len(pre_a) > len(pre_b):
        return 1
    if len(pre_a) < len(pre_b):
        return -1

    return 0
