import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_nodes = set(deps.keys())
    for dependencies in deps.values():
        all_nodes.update(dependencies)

    in_degree = {node: 0 for node in all_nodes}
    graph = {node: [] for node in all_nodes}

    for item, dependencies in deps.items():
        in_degree[item] = len(dependencies)
        for dep in dependencies:
            graph[dep].append(item)

    # Priority queue ensures we take the alphabetically smallest ready item
    ready_nodes = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready_nodes)

    order = []
    while ready_nodes:
        current = heapq.heappop(ready_nodes)
        order.append(current)

        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(ready_nodes, neighbor)

    if len(order) != len(all_nodes):
        raise ValueError("Cycle detected")

    return order
```

