def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    lines = []
    current_line = ""

    for word in words:
        if len(word) > width:
            # If there's an existing line being built, push it first
            if current_line:
                lines.append(current_line)
                current_line = ""

            # Split the long word into chunks of 'width'
            for i in range(0, len(word), width):
                lines.append(word[i : i + width])
        else:
            if not current_line:
                current_line = word
            elif len(current_line) + 1 + len(word) <= width:
                current_line += " " + word
            else:
                lines.append(current_line)
                current_line = word

    if current_line:
        lines.append(current_line)

    return lines
