from datetime import datetime

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    latest_map = {}
    appearance_order = []
    seen_keys = set()

    for record in records:
        val = record[key]

        if val not in seen_keys:
            seen_keys.add(val)
            appearance_order.append(val)

        # Handle ISO 8601 strings, including 'Z' suffix for UTC
        ts_str = record['updated_at'].replace('Z', '+00:00')
        current_dt = datetime.fromisoformat(ts_str)

        if val not in latest_map:
            latest_map[val] = {'record': record, 'dt': current_dt}
        else:
            # If current is later than or equal to the stored one, update it.
            # Equality ensures we keep the record that comes later in the list.
            if current_dt >= latest_map[val]['dt']:
                latest_map[val] = {'record': record, 'dt': current_dt}

    return [latest_map[v]['record'] for v in appearance_order]
