import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        # Parse the input IP address
        ip_obj = ipaddress.ip_address(ip)
    except ValueError:
        return False

    # Helper to check if an IP is an IPv4-mapped IPv6 address
    # and return the corresponding IPv4Address object.
    def get_mapped_ipv4(addr):
        if isinstance(addr, ipaddress.IPv6Address):
            # IPv4-mapped IPv6 addresses look like ::ffff:w.x.y.z
            # Their packed representation starts with 10 bytes of 0, 
            # then 2 bytes of 0xff, then 4 bytes of the IPv4 address.
            packed = addr.packed
            if packed[:10] == b'\x00' * 10 and packed[10:12] == b'\xff\xff':
                return ipaddress.IPv4Address(packed[12:])
        return None

    # Determine the "base" address to check against networks
    # If it's a mapped IPv4, we treat it as an IPv4 address.
    mapped_addr = get_mapped_ipv4(ip_obj)

    # We iterate through networks and check membership.
    # A mapped IPv4 address counts as the IPv4 address it carries.
    for net_str in networks:
        try:
            # strict=False allows networks with host bits set (e.g., 10.0.0.1/8 -> 10.0.0.0/8)
            net_obj = ipaddress.ip_network(net_str, strict=False)

            # If the input is a mapped IPv4, check against the network as an IPv4.
            # If the network is IPv4, we compare the mapped IPv4.
            # If the network is IPv6, the mapped IPv4 logic doesn't apply as per instructions.
            if mapped_addr:
                if isinstance(net_obj, ipaddress.IPv4Network):
                    if mapped_addr in net_obj:
                        return True
                else:
                    # If it's an IPv6 network, does the mapped address count?
                    # "counts as the IPv4 address it carries" suggests we compare 
                    # the extracted IPv4. However, an IPv4 address is not "in" an 
                    # IPv6 network. If the prompt implies it should be checked 
                    # against the network, we only check if the type matches.
                    pass
            else:
                # Standard check for non-mapped IPv4 or IPv6 addresses
                if ip_obj in net_obj:
                    return True
        except ValueError:
            raise ValueError(f"Invalid network: {net_str}")

    return False
